136	    /**
137	     * Return the owner's address. When a structured address is supplied (a non-blank
138	     * {@code addressLine1}) it takes precedence and the value is composed as the
139	     * normalized {@code addressLine1}, with a single space and the normalized
140	     * {@code addressLine2} appended when an {@code addressLine2} is present.
141	     * Otherwise the flat {@code address} is returned, preserving backward
142	     * compatibility for owners supplied in the flat form.
143	     */
144	    public String getAddress() {
145	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
146	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
147	                return this.addressLine1 + " " + this.addressLine2;
148	            }
149	            return this.addressLine1;
150	        }
151	        return this.address;
152	    }
