154	    /**
155	     * Set the owner's flat address, normalizing it to a canonical form so it is both
156	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
157	     * internal runs of whitespace are collapsed to a single space, the value is
158	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
159	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
160	     * left as-is.
161	     */
162	    public void setAddress(String address) {
163	        this.address = normalizeAddress(address);
164	    }
