193	    /**
194	     * Normalize an address string to its canonical form: trimmed, whitespace
195	     * collapsed, upper-cased, with common street-type abbreviations expanded.
196	     * Returns {@code null} for a {@code null} input; a value that is blank once
197	     * trimmed normalizes to the empty string.
198	     */
199	    public static String normalizeAddress(String address) {
200	        if (address == null) {
201	            return null;
202	        }
203	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
204	        if (collapsed.isEmpty()) {
205	            return "";
206	        }
207	        String[] tokens = collapsed.split(" ");
208	        StringBuilder sb = new StringBuilder();
209	        for (int i = 0; i < tokens.length; i++) {
210	            if (i > 0) {
211	                sb.append(' ');
212	            }
213	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
214	        }
215	        return sb.toString();
216	    }
