336	    /**
337	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
338	     * is always valid (postcode is optional). When present, a postcode is valid if
339	     * the city has no known region, or if it is four digits falling within the
340	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
341	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
342	     */
343	    public boolean isPostcodeValidForCity() {
344	        if (this.postcode == null) {
345	            return true;
346	        }
347	        String region = CITY_REGION.get(this.city);
348	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
349	        if (range == null) {
350	            return true;
351	        }
352	        if (!this.postcode.matches("^[0-9]{4}$")) {
353	            return false;
354	        }
355	        int value = Integer.parseInt(this.postcode);
356	        return value >= range[0] && value <= range[1];
357	    }
