367	    /**
368	     * Return a single Luhn check digit (0-9) computed over the digits contained in
369	     * the owner's customer code, or {@code null} when the customer code is not set.
370	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
371	     * first, following the standard Luhn algorithm.
372	     */
373	    public Integer getCheckDigit() {
374	        if (this.customerCode == null) {
375	            return null;
376	        }
377	        int sum = 0;
378	        boolean doubleDigit = true;
379	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
380	            char c = this.customerCode.charAt(i);
381	            if (c < '0' || c > '9') {
382	                continue;
383	            }
384	            int digit = c - '0';
385	            if (doubleDigit) {
386	                digit *= 2;
387	                if (digit > 9) {
388	                    digit -= 9;
389	                }
390	            }
391	            sum += digit;
392	            doubleDigit = !doubleDigit;
393	        }
394	        return (10 - (sum % 10)) % 10;
395	    }
