397	    /**
398	     * Return the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY}
399	     * is the last two digits of the fiscal year derived from the (business-day
400	     * adjusted) registration date. The fiscal year starts on 1 July and is named
401	     * after the calendar year in which it ends, so a registration date on or after
402	     * 1 July belongs to the fiscal year ending the following calendar year (for
403	     * example {@code 2026-08-14 -> 'FY27'}), while a date before 1 July belongs to
404	     * the fiscal year ending in that same calendar year. Returns {@code null} when
405	     * the registration date is not set.
406	     */
407	    public String getFiscalYear() {
408	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
409	        if (fiscalYear == null) {
410	            return null;
411	        }
412	        return String.format("FY%02d", fiscalYear % 100);
413	    }
