453	    /**
454	     * Return the owner's membership points, the raw score from which the
455	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
456	     * email address is present, {@code 1} when the owner has no namesakes
457	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
458	     * more, and {@code 3} when the owner's tenure (the number of fiscal years
459	     * elapsed since the registration date, the fiscal year starting on 1 July) is
460	     * at least {@code 1}.
461	     */
462	    public Integer getMembershipPoints() {
463	        int points = 0;
464	        boolean hasEmail = this.email != null && !this.email.isBlank();
465	        if (hasEmail) {
466	            points += 2;
467	        }
468	        if (this.namesakeCount != null && this.namesakeCount == 0) {
469	            points += 1;
470	        }
471	        if (this.householdSize != null && this.householdSize >= 3) {
472	            points += 2;
473	        }
474	        Integer registrationFiscalYear = fiscalYearOf(this.registrationDate);
475	        if (registrationFiscalYear != null) {
476	            int elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - registrationFiscalYear;
477	            if (elapsedFiscalYears >= 1) {
478	                points += 3;
479	            }
480	        }
481	        return points;
482	    }
483	
484	    /**
485	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
486	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
487	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
488	     * {@code 4} for {@code 6} or more. When a {@code membershipLevelCap} is set,
489	     * the derived level is capped at it (a level higher than the cap is lowered to
490	     * the cap); the cap records one above the maximum level among the owner's
491	     * household members at creation time.
492	     */
493	    public Integer getMembershipLevel() {
494	        int points = getMembershipPoints();
495	        int level;
496	        if (points >= 6) {
497	            level = 4;
498	        }
499	        else if (points >= 4) {
500	            level = 3;
501	        }
502	        else if (points >= 2) {
503	            level = 2;
504	        }
505	        else {
506	            level = 1;
507	        }
508	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
509	            return this.membershipLevelCap;
510	        }
511	        return level;
512	    }
513	
