617	    /**
618	     * Return the owner's IANA timezone, derived from the locality/region via the
619	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
620	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
621	     * {@code null} when the region is not in the table.
622	     */
623	    public String getTimezone() {
624	        return REGION_TIMEZONE.get(getLocality());
625	    }
626	
627	    /**
628	     * Look up the region whose inclusive postcode range contains this owner's
629	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
630	     * known range.
631	     */
632	    private String regionForPostcode() {
633	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
634	            return null;
635	        }
636	        int value = Integer.parseInt(this.postcode);
637	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
638	            int[] range = entry.getValue();
639	            if (value >= range[0] && value <= range[1]) {
640	                return entry.getKey();
641	            }
642	        }
643	        return null;
644	    }
645	
646	    /**
647	     * Return the owner's preferred contact channel, derived from the stored
648	     * contact details: {@code 'EMAIL'} when an email address is present,
649	     * otherwise {@code 'PHONE'}.
650	     */
651	    public String getContactPreference() {
652	        boolean hasEmail = this.email != null && !this.email.isBlank();
653	        return hasEmail ? "EMAIL" : "PHONE";
654	    }
655	
656	    /**
657	     * Return the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
658	     * {@code TIER} is {@code 'PREMIUM'} when the {@link #getMembershipLevel()
659	     * membership level} is {@code 3} or more, otherwise {@code 'STANDARD'}.
660	     * {@code AREA} is {@code 'METRO'} when the {@link #getLocality() locality}
661	     * is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
662	     * {@code 'REGIONAL'}.
663	     */
664	    public String getOwnerSegment() {
665	        Integer membershipLevel = getMembershipLevel();
666	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
667	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
668	        return tier + "_" + area;
669	    }
670	
671	    /**
672	     * Return the owner's derived identity key, which consolidates all duplicate
673	     * detection into a single value: the SHA-256 digest, rendered as 64 lower-case
674	     * hex characters, of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
675	     * The telephone and email are already stored in their normalized (E.164 /
676	     * lower-cased) forms; a missing email contributes an empty segment and the last
677	     * name is reduced to its Soundex code. A create is rejected only when a new
678	     * owner's whole identity key equals an existing owner's.
679	     */
680	    public String getIdentityKey() {
681	        String telephonePart = this.telephone == null ? "" : this.telephone;
682	        String emailPart = (this.email == null) ? "" : this.email.toLowerCase(Locale.ROOT);
683	        String soundexPart = soundex(getLastName());
684	        String key = telephonePart + "|" + emailPart + "|" + soundexPart;
685	        try {
686	            byte[] digest = MessageDigest.getInstance("SHA-256")
687	                .digest(key.getBytes(StandardCharsets.UTF_8));
688	            StringBuilder sb = new StringBuilder(digest.length * 2);
689	            for (byte b : digest) {
690	                sb.append(String.format("%02x", b));
691	            }
692	            return sb.toString();
693	        }
694	        catch (NoSuchAlgorithmException e) {
695	            throw new IllegalStateException(e);
696	        }
697	    }
698	
699	    /**
700	     * Compute the American Soundex code of the given name: its first letter followed
701	     * by three digits derived from the remaining consonants (vowels act as separators,
702	     * {@code H} and {@code W} are transparent, and adjacent equal codes collapse),
703	     * zero-padded and truncated to four characters. Returns an empty string when the
704	     * name is {@code null} or holds no letters.
705	     */
706	    public static String soundex(String name) {
707	        if (name == null) {
708	            return "";
709	        }
710	        StringBuilder letters = new StringBuilder();
711	        for (int i = 0; i < name.length(); i++) {
712	            char c = name.charAt(i);
713	            if (Character.isLetter(c)) {
714	                letters.append(Character.toUpperCase(c));
715	            }
716	        }
717	        if (letters.length() == 0) {
718	            return "";
719	        }
720	        StringBuilder code = new StringBuilder();
721	        code.append(letters.charAt(0));
722	        char prevDigit = soundexDigit(letters.charAt(0));
723	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
724	            char c = letters.charAt(i);
725	            if (c == 'H' || c == 'W') {
726	                continue;
727	            }
728	            char digit = soundexDigit(c);
729	            if (digit != '0' && digit != prevDigit) {
730	                code.append(digit);
731	            }
732	            prevDigit = digit;
733	        }
734	        while (code.length() < 4) {
735	            code.append('0');
736	        }
737	        return code.toString();
738	    }
739	
740	    private static char soundexDigit(char c) {
741	        switch (c) {
742	            case 'B': case 'F': case 'P': case 'V':
743	                return '1';
744	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
745	                return '2';
746	            case 'D': case 'T':
747	                return '3';
748	            case 'L':
749	                return '4';
750	            case 'M': case 'N':
751	                return '5';
752	            case 'R':
753	                return '6';
754	            default:
755	                return '0';
756	        }
757	    }
758	
759	    protected Set<Pet> getPetsInternal() {
760	        if (this.pets == null) {
761	            this.pets = new HashSet<>();
762	        }
763	        return this.pets;
764	    }
765	
766	    protected void setPetsInternal(Set<Pet> pets) {
767	        this.pets = pets;
768	    }
769	
770	    public List<Pet> getPets() {
771	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
772	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
773	        return Collections.unmodifiableList(sortedPets);
774	    }
775	
776	    public void setPets(List<Pet> pets) {
777	        this.pets = new HashSet<>(pets);
778	    }
779	
780	    public void addPet(Pet pet) {
781	        getPetsInternal().add(pet);
782	        pet.setOwner(this);
783	    }
784	
785	    /**
786	     * Return the Pet with the given name, or null if none found for this Owner.
787	     *
788	     * @param name to test
789	     * @return true if pet name is already in use
790	     */
791	    public Pet getPet(String name) {
792	        return getPet(name, false);
793	    }
794	
795	    /**
796	     * Return the Pet with the given name, or null if none found for this Owner.
797	     *
798	     * @param name to test
799	     * @return true if pet name is already in use
800	     */
801	    public Pet getPet(String name, boolean ignoreNew) {
802	        name = name.toLowerCase();
803	        for (Pet pet : getPetsInternal()) {
804	            if (!ignoreNew || !pet.isNew()) {
805	                String compName = pet.getName();
806	                compName = compName.toLowerCase();
807	                if (compName.equals(name)) {
808	                    return pet;
809	                }
810	            }
811	        }
812	        return null;
813	    }
814	
815	    public Pet getPet(Integer petId) {
816	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
817	    }
818	
819	    @Override
820	    public String toString() {
821	        return new ToStringCreator(this)
822	
823	            .append("id", this.getId())
824	            .append("new", this.isNew())
825	            .append("lastName", this.getLastName())
826	            .append("firstName", this.getFirstName())
827	            .append("address", this.address)
828	            .append("city", this.city)
829	            .append("telephone", this.telephone)
830	            .append("email", this.email)
831	            .toString();
832	    }
833	}
