64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit trail for owner-lifecycle side effects. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /**
77	     * Monotonically increasing sequence stamped onto each {@code OWNER_CREATED} audit
78	     * event, so consumers can order and de-duplicate events across the lifetime of the
79	     * application. Shared across all creates; never reset.
80	     */
81	    private static final AtomicInteger CREATE_SEQUENCE = new AtomicInteger();
82	
83	    /** Serializer for the structured audit event; records serialize by their components. */
84	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
85	
86	    /**
87	     * Immutable structured audit event emitted on owner creation. Its component order
88	     * ({@code seq}, {@code ownerId}, {@code customerCode}, {@code membershipLevel},
89	     * {@code event}) is also the field order of the serialized JSON. The
90	     * {@code customerCode} slot carries the owner's current primary identifier — the
91	     * customer code today, and whatever unifies it later (e.g. a member id).
92	     */
93	    private record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode,
94	                                     Integer membershipLevel, String event) {
95	    }
96	
97	    /** Email domains from disposable/throwaway providers, rejected on create. */
98	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
99	        "mailinator.com", "tempmail.com", "guerrillamail.com");
100	
101	    /** Request header carrying an idempotency token for owner creation. */
102	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
103	
104	    /**
105	     * Remembers the owner created under each seen {@code Idempotency-Key}, so a repeated
106	     * create with an already-seen key returns the original owner (200) instead of creating
107	     * a duplicate. Keyed by the header value, mapped to the created owner's id.
108	     */
109	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
110	
111	    private final ClinicService clinicService;
112	
113	    private final OwnerMapper ownerMapper;
114	
115	    private final PetMapper petMapper;
116	
117	    private final VisitMapper visitMapper;
118	
119	    public OwnerRestControllerV1(ClinicService clinicService,
120	                                 OwnerMapper ownerMapper,
121	                                 PetMapper petMapper,
122	                                 VisitMapper visitMapper) {
123	        this.clinicService = clinicService;
124	        this.ownerMapper = ownerMapper;
125	        this.petMapper = petMapper;
126	        this.visitMapper = visitMapper;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
132	        Collection<Owner> owners;
133	        if (lastName != null) {
134	            owners = this.clinicService.findOwnerByLastName(lastName);
135	        } else {
136	            owners = this.clinicService.findAllOwners();
137	        }
138	        if (owners.isEmpty()) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
158	        // seen, return the owner originally created under it (200) rather than creating a
159	        // duplicate. The key is remembered only after a successful create below.
160	        String idempotencyKey = currentIdempotencyKey();
161	        if (idempotencyKey != null) {
162	            Integer existingId = idempotentCreates.get(idempotencyKey);
163	            if (existingId != null) {
164	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
165	                if (existingOwner != null) {
166	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
167	                }
168	            }
169	        }
170	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
171	        if (normalizedTelephone == null) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
175	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	        }
177	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
178	        // The owner must supply an address in EITHER form: a non-blank structured
179	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
180	        // fields (composing line 1 with an optional line 2) and falls back to the flat
181	        // value; a blank result means neither form was provided. The composed value is
182	        // written back so the persisted flat 'address' stays consistent with it.
183	        String composedAddress = owner.getAddress();
184	        if (composedAddress == null || composedAddress.isBlank()) {
185	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
186	        }
187	        owner.setAddress(composedAddress);
188	        owner.setTelephone(normalizedTelephone);
189	        if (!owner.isPostcodeValidForCity()) {
190	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
191	        }
192	        // The household id is deterministic: it is derived purely from the owner's
193	        // (last name, postcode), so every owner at the same last name and postcode resolves
194	        // to the same value. It is assigned up front, before any duplicate detection, so the
195	        // identity key and the household check below both key off it.
196	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
197	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
198	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
199	        // identityKey (the SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName))
200	        // equals an existing owner's. Because the telephone is part of the key, two owners
201	        // sharing only a last name and postcode differ here whenever their telephone or email
202	        // differs, and so are both allowed (the second is surfaced as a soft match below). This
203	        // single identity key is now the only 409 duplicate check — the former separate
204	        // household-duplicate block keyed on the computed household id no longer applies.
205	        String identityKey = owner.getIdentityKey();
206	        if (this.clinicService.findAllOwners().stream()
207	            .filter(existing -> !existing.isDeleted())
208	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        // The household id is still computed for household-size and membership-level purposes,
212	        // but sharing it no longer rejects the create.
213	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
214	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
215	        if (ownersInCity >= 50) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        boolean capacityWarning = ownersInCity >= 40 && ownersInCity <= 49;
219	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
220	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
221	        }
222	        LocalDate effectiveDate =
223	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
224	        LocalDate registrationDate = toBusinessDay(effectiveDate);
225	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
226	        if (ownersRegisteredToday >= 100) {
227	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
228	        }
229	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
230	        HttpHeaders headers = new HttpHeaders();
231	        owner.setRegistrationDate(registrationDate);
232	        owner.setCustomerCode(customerCode(owner));
233	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
234	        owner.setBulkSignupWarning(bulkSignupWarning);
235	        owner.setCapacityWarning(capacityWarning);
236	        // The household size (an input to the membership computation) keys off the computed
237	        // household id: this owner plus everyone already sharing it.
238	        owner.setHouseholdSize(householdMembers.size() + 1);
239	        // Level ceiling: a new owner joining a household they did not explicitly declare
240	        // may not out-rank the household. Cap the derived membership level at one above the
241	        // current maximum among the existing household members; with no existing member no
242	        // cap applies.
243	        if (!sharesHousehold && !householdMembers.isEmpty()) {
244	            int maxHouseholdLevel = householdMembers.stream()
245	                .mapToInt(Owner::getMembershipLevel)
246	                .max()
247	                .orElse(0);
248	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
249	        }
250	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
251	        // duplicate, so only a non-declared create is scored. A non-declared owner whose
252	        // identity key differs from an existing owner's but whose last name (by Soundex) and
253	        // postcode match is flagged here as a possible duplicate rather than rejected.
254	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
255	        owner.setPossibleDuplicate(possibleDuplicate != null);
256	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
257	        this.clinicService.saveOwner(owner);
258	        if (idempotencyKey != null) {
259	            idempotentCreates.put(idempotencyKey, owner.getId());
260	        }
261	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
262	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
263	            owner.getMembershipNumber());
264	        emitOwnerCreatedEvent(owner);
265	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
274	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
275	        if (currentOwner == null) {
276	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	        }
278	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
279	        if (normalizedTelephone == null) {
280	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
281	        }
282	        currentOwner.setAddress(ownerFieldsDto.getAddress());
283	        currentOwner.setCity(ownerFieldsDto.getCity());
284	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
285	        currentOwner.setLastName(ownerFieldsDto.getLastName());
286	        currentOwner.setTelephone(normalizedTelephone);
287	        currentOwner.setEmail(ownerFieldsDto.getEmail());
288	        this.clinicService.saveOwner(currentOwner);
289	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Transactional
294	    @Override
295	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
296	        Owner owner = this.clinicService.findOwnerById(ownerId);
297	        if (owner == null) {
298	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	        }
300	        // Soft-delete: retain the row and flag it deleted rather than removing it. The owner
301	        // remains readable via GET, and is subsequently ignored by the create endpoint's
302	        // duplicate and identity checks.
303	        owner.setDeleted(true);
304	        this.clinicService.saveOwner(owner);
305	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        HttpHeaders headers = new HttpHeaders();
316	        Pet pet = petMapper.toPet(petFieldsDto);
317	        owner.setId(ownerId);
318	        pet.setOwner(owner);
319	        pet.getType().setName(null);
320	        this.clinicService.savePet(pet);
321	        PetDto petDto = petMapper.toPetDto(pet);
322	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
323	            .buildAndExpand(pet.getId()).toUri());
324	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
330	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
331	        if (currentOwner != null) {
332	            Pet currentPet = this.clinicService.findPetById(petId);
333	            if (currentPet != null) {
334	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
335	                currentPet.setName(petFieldsDto.getName());
336	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
337	                this.clinicService.savePet(currentPet);
338	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
339	            }
340	        }
341	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	    }
343	
344	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
345	    @Override
346	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
347	        HttpHeaders headers = new HttpHeaders();
348	        Visit visit = visitMapper.toVisit(visitFieldsDto);
349	        Pet pet = new Pet();
350	        pet.setId(petId);
351	        visit.setPet(pet);
352	        this.clinicService.saveVisit(visit);
353	        VisitDto visitDto = visitMapper.toVisitDto(visit);
354	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
355	            .buildAndExpand(visit.getId()).toUri());
356	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
357	    }
358	
359	
360	    /**
361	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
362	     * stripped. When a leading {@code '+'} and country code are present they are kept;
363	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
364	     * is dropped from the national digits. The result must be a {@code '+'} followed
365	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
366	     * is returned to signal a bad request.
367	     */
368	    /**
369	     * Build the customer code for a newly created owner, formatted
370	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
371	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
372	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
373	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
374	     * with its last name. This identity carries no sequence number.
375	     */
376	    private String customerCode(Owner owner) {
377	        String region = owner.getLocality();
378	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
379	        String base = region + "-" + hash8;
380	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
381	            .map(Owner::getCustomerCode)
382	            .filter(java.util.Objects::nonNull)
383	            .collect(java.util.stream.Collectors.toSet());
384	        if (!existing.contains(base)) {
385	            return base;
386	        }
387	        int n = 2;
388	        while (existing.contains(base + "-" + n)) {
389	            n++;
390	        }
391	        return base + "-" + n;
392	    }
393	
394	    /**
395	     * Emit the immutable structured {@code OWNER_CREATED} audit event for a freshly
396	     * created owner: a JSON object {@code {seq, ownerId, customerCode, membershipLevel,
397	     * event}} logged to the dedicated {@code AUDIT} trail alongside the human-readable
398	     * audit line. Each event is stamped with the next value of the shared monotonic
399	     * sequence, and carries the owner's current primary identifier.
400	     */
401	    private void emitOwnerCreatedEvent(Owner owner) {
402	        OwnerCreatedEvent event = new OwnerCreatedEvent(
403	            CREATE_SEQUENCE.incrementAndGet(),
404	            owner.getId(),
405	            primaryIdentifier(owner),
406	            owner.getMembershipLevel(),
407	            "OWNER_CREATED");
408	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
409	    }
410	
411	    /**
412	     * The owner's current primary identifier, as carried by the structured audit event.
413	     * Today this is the customer code; when the customer code is later unified into a
414	     * member id, this returns that member id instead and the event follows automatically.
415	     */
416	    private String primaryIdentifier(Owner owner) {
417	        return owner.getCustomerCode();
418	    }
419	
420	    /**
421	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
422	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
423	     * treated as empty when {@code null}), already in their normalized forms.
424	     */
425	    private String customerCodeHash(String telephone, String lastName) {
426	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
427	        try {
428	            byte[] digest = MessageDigest.getInstance("SHA-256")
429	                .digest(key.getBytes(StandardCharsets.UTF_8));
430	            StringBuilder sb = new StringBuilder();
431	            for (int i = 0; i < 4; i++) {
432	                sb.append(String.format("%02X", digest[i]));
433	            }
434	            return sb.toString();
435	        }
436	        catch (NoSuchAlgorithmException e) {
437	            throw new IllegalStateException(e);
438	        }
439	    }
440	
441	    /**
442	     * Count the existing owners whose city matches the given one, compared after
443	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
444	     * cap: a city that already holds this many owners is at capacity.
445	     */
446	    private long countOwnersInCity(String city) {
447	        String normalizedCity = normalizeForHousehold(city);
448	        return this.clinicService.findAllOwners().stream()
449	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
450	            .count();
451	    }
452	
453	    /**
454	     * Count the existing owners whose registration date falls on the given day. Used to
455	     * enforce the per-day create limit: once this many owners have been registered today,
456	     * the day is at capacity and further creates are rejected.
457	     */
458	    private long countOwnersRegisteredOn(LocalDate day) {
459	        return this.clinicService.findAllOwners().stream()
460	            .filter(existing -> day.equals(existing.getRegistrationDate()))
461	            .count();
462	    }
463	
464	    /**
465	     * The fixed public holidays that the business-day roll skips. A registration date
466	     * landing on one of these is treated like a weekend and advanced to the next
467	     * non-holiday business day.
468	     */
469	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
470	        LocalDate.parse("2026-01-01"),
471	        LocalDate.parse("2026-01-26"),
472	        LocalDate.parse("2026-04-25"),
473	        LocalDate.parse("2026-12-25"),
474	        LocalDate.parse("2026-12-28"));
475	
476	    /**
477	     * Roll a registration date forward to the next business day: a date falling on a
478	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
479	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
480	     */
481	    private LocalDate toBusinessDay(LocalDate date) {
482	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
483	            date = date.plusDays(1);
484	        }
485	        return date;
486	    }
487	
488	    private static boolean isWeekend(LocalDate date) {
489	        DayOfWeek dayOfWeek = date.getDayOfWeek();
490	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
491	    }
492	
493	    /**
494	     * Find the existing owners that already belong to the same household as the given
495	     * computed household id. Because the household id is derived deterministically from
496	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
497	     * that last name and postcode.
498	     */
499	    private List<Owner> findHouseholdMembers(String householdId) {
500	        if (householdId == null) {
501	            return List.of();
502	        }
503	        return this.clinicService.findAllOwners().stream()
504	            .filter(existing -> !existing.isDeleted())
505	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
506	            .toList();
507	    }
508	
509	    /**
510	     * Find an existing owner that this new owner softly duplicates: one whose last name has
511	     * the same Soundex code and whose postcode matches, but whose whole identity key differs
512	     * (an equal identity key is a hard duplicate, already rejected above with 409). Returns
513	     * the lowest-id such owner, or {@code null} when the new owner has no postcode or no soft
514	     * match exists. Owners flagged deleted are ignored.
515	     */
516	    private Owner findPossibleDuplicate(Owner owner) {
517	        String postcode = owner.getPostcode();
518	        if (postcode == null) {
519	            return null;
520	        }
521	        String soundex = Owner.soundex(owner.getLastName());
522	        String identityKey = owner.getIdentityKey();
523	        return this.clinicService.findAllOwners().stream()
524	            .filter(existing -> !existing.isDeleted())
525	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
526	                && postcode.equals(existing.getPostcode())
527	                && !identityKey.equals(existing.getIdentityKey()))
528	            .min(java.util.Comparator.comparing(Owner::getId))
529	            .orElse(null);
530	    }
531	
532	    /**
533	     * Count the existing owners that already share both the given first and last
534	     * name, compared case-insensitively. Used to populate an owner's namesake count
535	     * at creation time, reflecting how many owners with the same name existed before
536	     * this one was created.
537	     */
538	    private int countNamesakes(String firstName, String lastName) {
539	        String normalizedFirstName = normalizeName(firstName);
540	        String normalizedLastName = normalizeName(lastName);
541	        return (int) this.clinicService.findAllOwners().stream()
542	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
543	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
544	            .count();
545	    }
546	
547	    private String normalizeName(String value) {
548	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
549	    }
550	
551	    /**
552	     * Build the deterministic identifier shared by all owners of one household: the first
553	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
554	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
555	     * name and postcode resolves to the same value regardless of creation order.
556	     */
557	    private String householdId(String lastName, String postcode) {
558	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
559	        try {
560	            byte[] digest = MessageDigest.getInstance("SHA-256")
561	                .digest(key.getBytes(StandardCharsets.UTF_8));
562	            StringBuilder sb = new StringBuilder();
563	            for (int i = 0; i < 6; i++) {
564	                sb.append(String.format("%02x", digest[i]));
565	            }
566	            return sb.toString();
567	        }
568	        catch (NoSuchAlgorithmException e) {
569	            throw new IllegalStateException(e);
570	        }
571	    }
572	
573	    private String normalizeForHousehold(String value) {
574	        if (value == null) {
575	            return "";
576	        }
577	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
578	    }
579	
580	    /** True when the email's domain is on the disposable-provider blocklist. */
581	    private boolean isDisposableEmailDomain(String email) {
582	        if (email == null) {
583	            return false;
584	        }
585	        int at = email.lastIndexOf('@');
586	        if (at < 0 || at == email.length() - 1) {
587	            return false;
588	        }
589	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
590	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
591	    }
592	
593	    /**
594	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
595	     * when it is absent or blank (the generated API signature does not expose it, so it is
596	     * pulled from the bound request attributes).
597	     */
598	    private String currentIdempotencyKey() {
599	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
600	            return null;
601	        }
602	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
603	        return (key == null || key.isBlank()) ? null : key;
604	    }
605	
606	    private String normalizeTelephone(String telephone) {
607	        if (telephone == null) {
608	            return null;
609	        }
610	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
611	        String digits;
612	        if (cleaned.startsWith("+")) {
613	            digits = cleaned.substring(1);
614	        } else {
615	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
616	            digits = "61" + national;
617	        }
618	        if (!digits.matches("[0-9]{8,15}")) {
619	            return null;
620	        }
621	        if (!hasValidNationalLength(digits)) {
622	            return null;
623	        }
624	        return "+" + digits;
625	    }
626	
627	    /**
628	     * Validate the national-number length of an E.164 number (the digits, without the
629	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
630	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
631	     * codes without a known rule are accepted as-is.
632	     */
633	    private boolean hasValidNationalLength(String digits) {
634	        if (digits.startsWith("61")) {
635	            return digits.length() - 2 == 9;
636	        }
637	        if (digits.startsWith("1")) {
638	            return digits.length() - 1 == 10;
639	        }
640	        return true;
641	    }
642	
643	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
644	    @Override
645	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
646	        Owner owner = this.clinicService.findOwnerById(ownerId);
647	        if (owner != null) {
648	            Pet pet = owner.getPet(petId);
649	            if (pet != null) {
650	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
651	            }
652	        }
653	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	    }
655	}
