2	
3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.junit.jupiter.api.Assertions.assertTrue;
6	import tools.jackson.databind.JsonNode;
7	
8	/** member-id: customerCode and membershipNumber are unified into 'memberId' =
9	 * '<REGION><FY><HASH8><CHK>'. Assert the exact, computable sub-values: the pinned region prefix and
10	 * the SHA-256 HASH8 over (telephone + lastName); and that the two old fields are gone. */
11	@Tag("cp56")
12	class Cp56Tests extends AcceptanceBase {
13	
14		@Test
15		void coreReturnsUnifiedMemberId() throws Exception {
16			JsonNode r = fetchOwner(createOwnerOk(knownOwner("Sydney"))); // region NSW
17			String hash8 = shaHex(r.get("telephone").asText() + r.get("lastName").asText(), 8);
18			String memberId = r.get("memberId").asText();
19			assertTrue(memberId.startsWith("NSW"), memberId);
20			assertTrue(memberId.contains(hash8), memberId + " should contain " + hash8);
21			assertTrue(!r.has("customerCode") && !r.has("membershipNumber"), "old id fields removed");
22		}
23	}
